const body = $input.first().json.body || $input.first().json;
const vendors = body.vendors || (body.website ? [{
  vendor_name: body.vendor_name || '',
  website: body.website,
  help_center_url: body.help_center_url || '',
  developer_docs_url: body.developer_docs_url || '',
  directory_category: body.directory_category || ''
}] : []);
if (!vendors.length) return [{ json: { _no_vendors: true } }];
const admin_url = (body.admin_url || 'http://127.0.0.1:8787').trim();
const openai_key = (body.openai_key || '').trim();
if (!openai_key) throw new Error('openai_key required in request body');
return vendors.map(v => ({
  json: {
    vendor_name: v.vendor_name || v.name || '',
    website: (v.website || '').replace(/\/$/, ''),
    help_center_url: v.help_center_url || '',
    developer_docs_url: v.developer_docs_url || '',
    directory_category: v.directory_category || '',
    admin_url,
    openai_key,
  }
}));

const item = $input.first().json;
// Resolve crawl URL: help_center_url -> developer_docs_url -> {website}/help
let crawl_url = '';
if (item.help_center_url && item.help_center_url.startsWith('http')) {
  crawl_url = item.help_center_url;
} else if (item.developer_docs_url && item.developer_docs_url.startsWith('http')) {
  crawl_url = item.developer_docs_url;
} else if (item.website) {
  crawl_url = item.website.replace(/\/$/, '') + '/help';
}
return [{ json: { ...item, crawl_url, crawl_attempted: !!crawl_url } }];

// Extract visible text from HTML — strip tags, collapse whitespace, cap at 6000 chars
const html = $input.first().json.data || $input.first().json || '';
const upstream = $input.first().json;
const text = String(html)
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&nbsp;/g, ' ')
  .replace(/\s+/g, ' ')
  .trim()
  .slice(0, 6000);
const crawl_ok = text.length > 150;
return [{ json: { ...upstream.passthroughData, crawl_text: text, crawl_ok } }];

// No crawl URL available — pass through with null score
const item = $input.first().json;
return [{ json: { ...item, crawl_text: '', crawl_ok: false } }];

// Merge crawl result branches
const item = $input.first().json;
return [{ json: item }];

