// Parse LLM response and compute raw score (sum of 6 dimensions, max 60)
const item = $input.first().json;
let scores = null;
let feature_signals = [];
try {
  const content = item.choices?.[0]?.message?.content || '';
  // Strip markdown code fences if present
  const clean = content.replace(/```json\s*/gi, '').replace(/```/g, '').trim();
  const parsed = JSON.parse(clean);
  scores = parsed.scores || null;
  feature_signals = (parsed.feature_signals || []).slice(0, 20);
} catch(e) {
  scores = null;
}
const upstream = item.passthroughData || item;
if (!scores) {
  return [{ json: { ...upstream, raw_score: null, feature_signals: [], llm_ok: false } }];
}
const dims = ['integrations', 'automation', 'reporting', 'onboarding', 'collaboration', 'api_developer'];
const raw_score = dims.reduce((sum, d) => sum + (Number(scores[d]) || 0), 0);
return [{ json: { ...upstream, raw_score, feature_signals, llm_ok: true, scores } }];

// Crawl failed — emit null score
const item = $input.first().json;
return [{ json: { ...item, raw_score: null, feature_signals: [], llm_ok: false } }];

// Merge LLM and null-score branches
const item = $input.first().json;
return [{ json: item }];

// Note: category-relative percentile ranking (0-100) requires all vendors in the same
// directory_category to be processed in one batch. This node collects all items and
// computes percentile ranks within each category group.
// For single-vendor calls, raw_score is mapped linearly (raw/60 * 100).
const items = $input.all();
const groups = {};
for (const item of items) {
  const cat = item.json.directory_category || '__unknown';
  if (!groups[cat]) groups[cat] = [];
  groups[cat].push(item.json);
}
const results = [];
for (const [cat, vendors] of Object.entries(groups)) {
  const scored = vendors.filter(v => v.raw_score !== null && v.raw_score !== undefined);
  const total = scored.length;
  for (const vendor of vendors) {
    let feature_depth_score = null;
    if (vendor.raw_score !== null && vendor.raw_score !== undefined) {
      if (total <= 1) {
        // Single vendor: linear mapping
        feature_depth_score = Math.round((vendor.raw_score / 60) * 100);
      } else {
        // Percentile rank within category
        const rank = scored.filter(v => v.raw_score < vendor.raw_score).length;
        feature_depth_score = Math.round((rank / (total - 1)) * 100);
      }
    }
    results.push({ json: { ...vendor, feature_depth_score } });
  }
}
return results;

const results = $input.all().map(item => ({
  vendor: item.json.vendor_name,
  website: item.json.website,
  feature_depth_score: item.json.feature_depth_score,
  feature_signals_count: (item.json.feature_signals || []).length,
  crawl_ok: item.json.crawl_ok,
  llm_ok: item.json.llm_ok,
  write_status: item.json.ok !== false ? 'ok' : 'error'
}));
return [{ json: { ok: true, results, total: results.length, scored: results.filter(r => r.feature_depth_score !== null).length } }];
